inputs = ['ux', 'xyheew', 'uczwg', 'gffkcz', 'ew']
outputs = ['uhi', 'hiyheew', 'ucuhjcwg', 'gffjccuhjc', 'ew']

# Manual implementation of find_minimal_edit
def find_minimal_edit(s_in, s_out):
    # Find the first position where strings differ
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return ("", s_out[len(s_in):], len(s_in))
        else:
            return (s_in[len(s_out):], "", len(s_out))

    # Find the extent of the difference
    old_sub = ""
    new_sub = ""

    # Look for the longest substring that matches
    i = pos
    while i < len(s_in) and i < len(s_out) and s_in[i] == s_out[i]:
        i += 1

    # For simplicity, let's just take single character changes for now
    if len(s_in) > len(s_out):
        # Deletion case
        old_sub = s_in[pos]
        new_sub = ""
    elif len(s_in) < len(s_out):
        # Insertion case  
        old_sub = ""
        new_sub = s_out[pos]
    else:
        # Substitution case
        old_sub = s_in[pos]
        new_sub = s_out[pos]

    return (old_sub, new_sub, pos)

# Analyze each changed pair
changed = [(0, 'ux', 'uhi'), (1, 'xyheew', 'hiyheew'), (2, 'uczwg', 'ucuhjcwg'), (3, 'gffkcz', 'gffjccuhjc')]

for idx, inp, outp in changed:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}'")
    print(f"  Change: '{old_sub}' -> '{new_sub}' at position {pos}")

